/**
 * Registers the app's OWN Swift Capacitor plugins with the iOS runtime.
 *
 * THE BUG THIS EXISTS TO FIX
 *
 * Capacitor 6 replaced iOS's load-time plugin registration with an explicit list:
 * ios/App/App/capacitor.config.json carries a "packageClassList", and the bridge registers
 * exactly the classes named there and nothing else.
 *
 * That list is generated by `npx cap sync ios`, which builds it by scanning the Swift files
 * of INSTALLED NPM PLUGIN PACKAGES for @objc(ClassName) — see
 * node_modules/@capacitor/cli/dist/util/iosplugin.js. IGNYT's HealthConnectPlugin does not
 * live in node_modules; it is a Swift file in the app target. The CLI therefore cannot see
 * it, has never listed it, and the runtime has never registered it.
 *
 * The result is the most misleading kind of failure. The plugin compiles. It is in the
 * target's Sources build phase. Its @objc name, its jsName and its CAPBridgedPlugin
 * conformance are all correct. Every static check passes — and on the device
 * Capacitor.Plugins.HealthConnect is undefined, so every health call fails and the app
 * reports that health data is unavailable. Days were spent looking at the Swift, at the
 * entitlement and at the App ID, none of which were ever wrong.
 *
 * WHY A SYNC HOOK RATHER THAN EDITING THE FILE
 *
 * writePluginJSON does `capJSON['packageClassList'] = classList` — it OVERWRITES, it does not
 * merge. Any hand-edit survives until the next `npx cap sync ios`, and Codemagic runs exactly
 * that on every build, so a hand-edit would work locally and never once in CI.
 *
 * Wired to Capacitor's own `capacitor:sync:after` hook in package.json, so it runs on every
 * sync, on this machine and on the build Mac, immediately after the CLI has written the list
 * it was going to write anyway.
 *
 * It DISCOVERS rather than hard-codes, so the next app-local plugin — a Swift notification
 * plugin, say — is picked up by existing.
 */

import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { join } from "node:path";

const NATIVE_DIR = join("ios", "App", "App");
const CONFIG = join(NATIVE_DIR, "capacitor.config.json");
const PACKAGE_SWIFT = join("ios", "App", "CapApp-SPM", "Package.swift");

/**
 * Undoes a Windows-only corruption the Capacitor CLI introduces on every `cap sync ios`.
 *
 * It rewrites Package.swift's local dependency path using the host's separator, so on Windows
 * the line becomes:
 *
 *     .package(name: "CapacitorApp", path: "..\..\..\node_modules\@capacitor\app")
 *
 * which is not merely ugly — it is broken Swift. A backslash starts an escape sequence in a
 * string literal, so `\n` in `\node_modules` is a newline and `\a` is invalid. The file itself
 * says "DO NOT MODIFY - managed by Capacitor CLI commands", and it is the CLI producing this.
 *
 * It is invisible from Windows because nothing here compiles Swift: the file sits modified in
 * the working tree, looks like ordinary sync churn in `git status`, and only fails on the build
 * Mac — after the minutes have been spent. Committing it once would break every iOS build until
 * someone read a Swift path closely enough to spot the slashes.
 *
 * Repaired here rather than gitignored, because the file genuinely does belong in the repo.
 */
function repairPackageSwift() {
  if (!existsSync(PACKAGE_SWIFT)) return;
  const before = readFileSync(PACKAGE_SWIFT, "utf8");
  // Only inside path: "..." literals, so nothing else in the file can be touched.
  const after = before.replace(/path:\s*"([^"]*)"/g, (m, p) => `path: "${p.replace(/\\/g, "/")}"`);
  if (after === before) return;
  writeFileSync(PACKAGE_SWIFT, after);
  console.log("[ios-register-app-plugins] repaired Windows backslashes in Package.swift");
}

repairPackageSwift();

/* Nothing to do on an Android-only checkout, or when the hook fires for android. */
if (!existsSync(CONFIG)) {
  console.log("[ios-register-app-plugins] no ios/App/App/capacitor.config.json — skipping");
  process.exit(0);
}

/* Both conditions are required, and neither alone is sufficient:
   - @objc(Name) is what exposes the class to the Objective-C runtime under a stable name
   - CAPPlugin is what makes it a plugin rather than any other @objc class in the target
   Matching on @objc alone would list AppDelegate the moment someone marks it @objc. */
const OBJC = /@objc\(([A-Za-z0-9_]+)\)/;
const IS_PLUGIN = /:\s*CAPPlugin\b|CAPBridgedPlugin/;

const found = [];
for (const file of readdirSync(NATIVE_DIR).filter(f => f.endsWith(".swift"))) {
  const src = readFileSync(join(NATIVE_DIR, file), "utf8");
  if (!IS_PLUGIN.test(src)) continue;
  const m = OBJC.exec(src);
  if (m?.[1] && !found.includes(m[1])) found.push(m[1]);
}

if (found.length === 0) {
  console.log("[ios-register-app-plugins] no app-local Swift plugins found — nothing to add");
  process.exit(0);
}

const config = JSON.parse(readFileSync(CONFIG, "utf8"));
const before = Array.isArray(config.packageClassList) ? config.packageClassList : [];
const added = found.filter(c => !before.includes(c));

if (added.length === 0) {
  console.log(`[ios-register-app-plugins] already registered: ${found.join(", ")}`);
  process.exit(0);
}

/* Appended, never replacing: the CLI's own entries are the npm plugins and must stay. */
config.packageClassList = [...before, ...added];
writeFileSync(CONFIG, JSON.stringify(config, null, "\t") + "\n");

console.log(`[ios-register-app-plugins] registered ${added.join(", ")}`);
console.log(`[ios-register-app-plugins] packageClassList is now: ${config.packageClassList.join(", ")}`);
